  _setUnitThresh(u, i, v) { var m = Object.assign({}, this.state.unitThresh); var a = (m[u] || []).slice(); var n = parseFloat(v); a[i] = isNaN(n) ? null : n; m[u] = a; this.setState({ unitThresh: m, dirty: true }); }
